    calculation_rule_code, calculation_type_code, unit_code,
    is_global, created_by, updated_by
) VALUES (
    #{id}, #{code}, #{name}, #{categoryId}, #{typeCode},
    #{calcRuleCode}, #{calcTypeCode}, #{unitCode},
    #{isGlobal}, #{createdBy}, #{createdBy}
)

