    id, cycle_id, master_kpi_id, target_description, target_value, weight,
    is_important, created_by, updated_by
) VALUES (
    #{id}, #{cycleId}, #{masterKpiId}, #{targetDescription}, #{targetValue}, #{weight},
    #{isImportant}, #{createdBy}, #{createdBy}
)

